#!/usr/bin/env bash
# Generated by lexichron new-project (from /opt/lexichron/host_kernel.sh).
#
# Starts a project's Jupyter kernel inside the image with the Slurm host
# bridge running beside it, so notebook code can submit and watch jobs: sbatch
# is on the host, not in the container, and lexichron.bridge reaches it
# through LEXICHRON_BRIDGE_DIR. The project's kernel.json runs this in place
# of host-python; its arguments go to host-python unchanged:
#
#   <project>/.venv/host-kernel -m ipykernel_launcher -f CONNECTION_FILE
#
# new-project rewrites this file on every run. To keep changes of your own,
# delete the "Generated by lexichron new-project" line: new-project then
# leaves the file alone and still points the kernel at it.
set -u
VENV="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd -P)"
PROJECT_DIR="$(dirname "$VENV")"
STATE_DIR="$PROJECT_DIR/.lexichron"
BRIDGE_SH="$STATE_DIR/host_bridge.sh"

# Without Slurm on this host (a laptop, a workstation) there is nothing to
# bridge to; the kernel starts as host-python would start it.
if command -v sbatch >/dev/null 2>&1 && [ -x "$BRIDGE_SH" ]; then
    # One bridge directory per kernel, named by host and this script's pid;
    # remove those of kernels on this host that are gone.
    host=$(hostname -s 2>/dev/null || hostname)
    for d in "$STATE_DIR"/bridge-kernel-"$host"-*/; do
        [ -d "$d" ] || continue
        pid=${d%/}; pid=${pid##*-}
        kill -0 "$pid" 2>/dev/null || rm -rf "$d"
    done
    BRIDGE_DIR="$STATE_DIR/bridge-kernel-$host-$$"
    mkdir -p "$BRIDGE_DIR"
    # The bridge exits when its parent goes away. exec below keeps this pid
    # for the kernel, so the bridge lives exactly as long as the kernel does.
    bash "$BRIDGE_SH" "$BRIDGE_DIR" >/dev/null 2>&1 &
    export LEXICHRON_BRIDGE_DIR="$BRIDGE_DIR"
fi
exec "$VENV/host-python" "$@"
